    Bug 2019525 - Make the "new messages" star appear on the folder pane again. r=freaktechnik

    Differential Revision: https://phabricator.services.mozilla.com/D285025

diff --git a/mail/base/content/about3Pane.xhtml b/mail/base/content/about3Pane.xhtml
index c9662afd109..9c1a27aa95e 100644
--- a/mail/base/content/about3Pane.xhtml
+++ b/mail/base/content/about3Pane.xhtml
@@ -107,6 +107,7 @@
         <div class="twisty">
           <img class="twisty-icon" src="chrome://global/skin/icons/arrow-down-12.svg" alt="" />
         </div>
+        <img class="new-icon" alt="" />
         <img class="icon" alt="" />
         <span class="name" tabindex="-1"></span>
         <span class="folder-count-badge unread-count"></span>
diff --git a/mail/themes/shared/mail/about3Pane.css b/mail/themes/shared/mail/about3Pane.css
index 50309649c5f..546177d8b2d 100644
--- a/mail/themes/shared/mail/about3Pane.css
+++ b/mail/themes/shared/mail/about3Pane.css
@@ -502,14 +502,19 @@ body {
     outline-offset: -1px;
   }

-  .new-messages:not([data-server-type]) > & > .icon::after {
-    position: absolute;
+  & > .new-icon {
+    z-index: 1;
     content: var(--icon-sparkle-star-xs);
-    inset-inline-start: -4px;
-    inset-block-start: -4px;
+    margin-inline: -4px -8px;
+    margin-block: -3px 3px;
     -moz-context-properties: fill, stroke;
     fill: var(--color-yellow-30);
     stroke: var(--color-amber-50);
+    visibility: hidden;
+
+    .new-messages:not([data-server-type]) > .container > & {
+      visibility: visible;
+    }
   }
 }
